import { defineConfig } from "vitest/config";

export default defineConfig({
  test: { environment: "node", include: ["test/**/*.test.ts"] },
});

from typing import Any, Dict


def ok_payload(content: str = "hello", model: str = "test-model") -> Dict[str, Any]:
    return {
        "id": "chatcmpl-test",
        "model": model,
        "choices": [
            {"index": 0, "message": {"role": "assistant", "content": content}, "finish_reason": "stop"}
        ],
        "usage": {"prompt_tokens": 3, "completion_tokens": 2, "total_tokens": 5},
    }

import { afterEach, beforeEach, expect, it } from "vitest";
import { Cerebras, Groq, Mistral, providersFromEnv } from "../src/index.js";

it("new providers construct with correct url/auth/models", () => {
  for (const [P, host] of [
    [Groq, "groq.com"],
    [Cerebras, "cerebras.ai"],
    [Mistral, "mistral.ai"],
  ] as const) {
    const p = new P("key");
    expect(p.url).toContain(host);
    expect(p.url.endsWith("/chat/completions")).toBe(true);
    expect(p.resolveModels("auto").length).toBeGreaterThan(0);
    expect(p.headers("key").Authorization).toBe("Bearer key");
    expect(p.discover).toBe(true);
  }
});

const ENV_KEYS = [
  "OPENROUTER_API_KEY", "GEMINI_API_KEY", "GOOGLE_API_KEY", "GOOGLE_AI_STUDIO_KEY",
  "NVIDIA_API_KEY", "NIM_API_KEY", "GROQ_API_KEY", "CEREBRAS_API_KEY", "MISTRAL_API_KEY",
  "FREELM_OPENROUTER_KEYS", "FREELM_GOOGLE_KEYS", "FREELM_NIM_KEYS",
  "FREELM_GROQ_KEYS", "FREELM_CEREBRAS_KEYS", "FREELM_MISTRAL_KEYS",
];
let saved: Record<string, string | undefined> = {};
beforeEach(() => {
  saved = {};
  for (const k of ENV_KEYS) {
    saved[k] = process.env[k];
    delete process.env[k];
  }
});
afterEach(() => {
  for (const k of ENV_KEYS) {
    if (saved[k] === undefined) delete process.env[k];
    else process.env[k] = saved[k];
  }
});

it("providersFromEnv picks up the configured providers", () => {
  process.env.GROQ_API_KEY = "gk";
  process.env.CEREBRAS_API_KEY = "ck";
  process.env.MISTRAL_API_KEY = "mk";
  const names = new Set(providersFromEnv().map((p) => p.name));
  expect(names.has("groq")).toBe(true);
  expect(names.has("cerebras")).toBe(true);
  expect(names.has("mistral")).toBe(true);
});

import { afterEach, expect, it, vi } from "vitest";
import { FreeLLM, OpenRouter } from "../src/index.js";
import { OpenAI } from "../src/compat/openai.js";

const OK = (content = "hi") =>
  JSON.stringify({
    id: "x",
    model: "m",
    choices: [{ index: 0, message: { role: "assistant", content }, finish_reason: "stop" }],
    usage: { prompt_tokens: 3, completion_tokens: 2, total_tokens: 5 },
  });

const SSE = ['data: {"choices":[{"delta":{"content":"Hel"}}]}', "", 'data: {"choices":[{"delta":{"content":"lo"}}]}', "", "data: [DONE]", ""].join("\n");

afterEach(() => {
  vi.unstubAllGlobals();
  delete process.env.OPENROUTER_API_KEY;
});

it("works with an explicit FreeLLM", async () => {
  vi.stubGlobal("fetch", vi.fn(async () => new Response(OK("compat"), { status: 200 })));
  const client = new OpenAI(new FreeLLM([new OpenRouter("k", { discover: false })]));
  const r = await client.chat.completions.create({ model: "auto", messages: [{ role: "user", content: "hi" }] });
  expect(r.choices[0].message.content).toBe("compat");
});

it("accepts OpenAI-SDK-style constructor options", async () => {
  process.env.OPENROUTER_API_KEY = "sk-or-env";
  vi.stubGlobal("fetch", vi.fn(async () => new Response(OK("ok"), { status: 200 })));
  // real OpenAI users construct with { apiKey, baseURL, ... } — must not break
  const client = new OpenAI({ apiKey: "sk-ignored", baseURL: "https://api.openai.com/v1", maxRetries: 2 });
  const r = await client.chat.completions.create({ model: "auto", messages: [{ role: "user", content: "hi" }] });
  expect(r.choices[0].message.content).toBe("ok");
});

it("stream: true yields chunk-shaped objects", async () => {
  vi.stubGlobal(
    "fetch",
    vi.fn(async () => new Response(SSE, { status: 200, headers: { "content-type": "text/event-stream" } })),
  );
  const client = new OpenAI(new FreeLLM([new OpenRouter("k", { discover: false })]));
  const stream = await client.chat.completions.create({
    model: "auto",
    messages: [{ role: "user", content: "hi" }],
    stream: true,
  });
  let out = "";
  for await (const chunk of stream) {
    expect(chunk.object).toBe("chat.completion.chunk");
    out += chunk.choices[0].delta.content ?? "";
  }
  expect(out).toBe("Hello");
});

import { afterEach, expect, it, vi } from "vitest";
import { FreeLLM, GoogleAIStudio, OpenRouter } from "../src/index.js";

const SSE =
  'data: {"choices":[{"delta":{"role":"assistant"}}]}\n\n' +
  'data: {"choices":[{"delta":{"content":"Hel"}}]}\n\n' +
  'data: {"choices":[{"delta":{"content":"lo"}}]}\n\n' +
  "data: [DONE]\n\n";

function mockFetch(handler: (url: string, init: any) => Promise<Response>) {
  vi.stubGlobal("fetch", vi.fn(handler as any));
}
afterEach(() => vi.unstubAllGlobals());

it("streams content deltas", async () => {
  mockFetch(async () => new Response(SSE, { status: 200, headers: { "content-type": "text/event-stream" } }));
  const llm = new FreeLLM([new OpenRouter("k", { discover: false })]);
  let out = "";
  for await (const chunk of llm.stream("hi")) out += chunk;
  expect(out).toBe("Hello");
});

it("fails over before the first token", async () => {
  mockFetch(async (url) =>
    url.includes("openrouter") ? new Response("account rate limit", { status: 429 }) : new Response(SSE, { status: 200 }),
  );
  const llm = new FreeLLM([new OpenRouter("k", { discover: false }), new GoogleAIStudio("k2")]);
  let out = "";
  for await (const chunk of llm.stream("hi")) out += chunk;
  expect(out).toBe("Hello");
});

import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";
import { save } from "../src/cache.js";
import { discover, toSpecs } from "../src/discovery.js";
import { OpenRouter } from "../src/providers/openrouter.js";

describe("toSpecs", () => {
  it("detects reasoning by name and orders it last", () => {
    const specs = toSpecs(
      [
        { id: "vendor/gpt-oss-120b", context_length: 8192 },
        { id: "vendor/llama-3.3-70b", context_length: 8192 },
      ],
      false,
    );
    expect(specs[0].id).toBe("vendor/llama-3.3-70b");
    expect(specs[specs.length - 1].id).toBe("vendor/gpt-oss-120b");
    expect(specs[specs.length - 1].tags).toContain("reasoning");
  });

  it("filters non-chat models", () => {
    const ids = toSpecs(
      [
        { id: "vendor/chat-70b", context_length: 8192 },
        { id: "whisper-large-v3" },
        { id: "vendor/text-embedding-3" },
        { id: "playai-tts" },
        { id: "vendor/llama-guard-8b", context_length: 8192 },
      ],
      false,
    ).map((s) => s.id);
    expect(ids).toEqual(["vendor/chat-70b"]);
  });

  it("free_only filter + order (large, small, reasoning)", () => {
    const ids = toSpecs(
      [
        { id: "vendor/big-70b:free", context_length: 131072, supported_parameters: ["tools"] },
        { id: "vendor/small-8b:free", context_length: 8192 },
        { id: "vendor/think-70b:free", context_length: 200000, supported_parameters: ["tools", "reasoning"] },
        { id: "vendor/paid-70b", context_length: 1000 },
      ],
      true,
    ).map((s) => s.id);
    expect(ids).toEqual(["vendor/big-70b:free", "vendor/small-8b:free", "vendor/think-70b:free"]);
  });
});

describe("discover", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
    delete process.env.FREELM_CACHE_DIR;
  });

  it("refetches live when the cached list yields no usable specs", async () => {
    process.env.FREELM_CACHE_DIR = mkdtempSync(join(tmpdir(), "freelm-test-"));
    save("openrouter", [{ id: "whisper-large-v3" }]); // filters down to nothing
    const live = { data: [{ id: "vendor/big-70b:free", context_length: 131072 }] };
    const fetchMock = vi.fn(async () => new Response(JSON.stringify(live), { status: 200 }));
    vi.stubGlobal("fetch", fetchMock);

    const p = new OpenRouter("k");
    expect(await discover(p)).toBe(true);
    expect(fetchMock).toHaveBeenCalledTimes(1); // stale-empty cache did not block the live fetch
    expect(p.models.map((m) => m.id)).toEqual(["vendor/big-70b:free"]);
  });
});

import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { main } from "../src/cli.js";

const OK = JSON.stringify({
  id: "x",
  model: "m",
  choices: [{ index: 0, message: { role: "assistant", content: "pong" }, finish_reason: "stop" }],
  usage: { prompt_tokens: 1, completion_tokens: 1, total_tokens: 2 },
});

const KEY_VARS = [
  "OPENROUTER_API_KEY", "FREELM_OPENROUTER_KEYS",
  "GEMINI_API_KEY", "GOOGLE_API_KEY", "GOOGLE_AI_STUDIO_KEY", "FREELM_GOOGLE_KEYS",
  "NVIDIA_API_KEY", "NIM_API_KEY", "FREELM_NIM_KEYS",
  "GROQ_API_KEY", "FREELM_GROQ_KEYS",
  "CEREBRAS_API_KEY", "FREELM_CEREBRAS_KEYS",
  "MISTRAL_API_KEY", "FREELM_MISTRAL_KEYS",
];

let out: string[];
let err: string[];

beforeEach(() => {
  process.env.FREELM_CACHE_DIR = mkdtempSync(join(tmpdir(), "freelm-cli-"));
  for (const v of KEY_VARS) delete process.env[v];
  out = [];
  err = [];
  vi.spyOn(process.stdout, "write").mockImplementation(((s: any) => (out.push(String(s)), true)) as any);
  vi.spyOn(process.stderr, "write").mockImplementation(((s: any) => (err.push(String(s)), true)) as any);
});

afterEach(() => {
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
  delete process.env.FREELM_CACHE_DIR;
  delete process.env.OPENROUTER_API_KEY;
});

it("--version prints the version", async () => {
  expect(await main(["--version"])).toBe(0);
  expect(out.join("")).toMatch(/freelm \d+\.\d+\.\d+/);
});

it("no args prints help", async () => {
  expect(await main([])).toBe(0);
  expect(out.join("")).toContain("chat");
});

it("no keys is a clean config error", async () => {
  expect(await main(["health"])).toBe(2);
  expect(err.join("")).toContain("config error");
});

it("chat prints the reply (provider note on stderr)", async () => {
  process.env.OPENROUTER_API_KEY = "sk-or-test";
  vi.stubGlobal(
    "fetch",
    vi.fn(async (url: any) =>
      String(url).includes("/models") ? new Response("nope", { status: 500 }) : new Response(OK, { status: 200 }),
    ),
  );
  expect(await main(["chat", "ping"])).toBe(0);
  expect(out.join("")).toContain("pong");
  expect(err.join("")).toContain("openrouter");
});

it("models lists the fallback catalog", async () => {
  process.env.OPENROUTER_API_KEY = "sk-or-test";
  vi.stubGlobal("fetch", vi.fn(async () => new Response("nope", { status: 500 })));
  expect(await main(["models", "--provider", "openrouter"])).toBe(0);
  const text = out.join("");
  expect(text).toContain("openrouter:");
  expect(text).toContain(":free");
});
